/**
 * Business identifiers.
 *
 * Every business row uses a nanoid, never an auto-increment integer: ids are
 * generated by whichever surface creates the row (tool, Web UI, future import)
 * before it reaches SQLite, so two databases can be merged without renumbering
 * and an id never leaks how many rows exist. A short type prefix keeps a raw id
 * readable in logs and makes an accidental cross-table reference obvious.
 *
 * @module
 */
import { nanoid } from 'nanoid'

/** Prefix per business entity; the prefix is not part of the nanoid itself. */
export const ID_PREFIXES = {
  requirement: 'req',
  designDoc: 'doc',
  story: 'sty',
  bug: 'bug',
  run: 'run',
} as const

/** Entity kinds that own a generated id. */
export type IdKind = keyof typeof ID_PREFIXES

/**
 * Create a new prefixed nanoid, e.g. `req_V1StGXR8_Z5jdHi6B-myT`.
 * @param kind - entity the id is for.
 * @returns a globally unique id with the matching prefix.
 */
export function newId(kind: IdKind): string {
  return `${ID_PREFIXES[kind]}_${nanoid()}`
}
